  "set.mcpTitle": { en: "Connected agents (MCP)", ms: "Agent bersambung (MCP)", zh: "已连接的代理（MCP）", ta: "இணைக்கப்பட்ட முகவர்கள் (MCP)", ar: "الوكلاء المتصلون (MCP)" },
  "set.mcpHelp": { en: "agents discover everything automatically via", ms: "agent jumpa semua automatik melalui", zh: "代理通过以下方式自动发现一切：", ta: "முகவர்கள் அனைத்தையும் தானாகக் கண்டறிவது:", ar: "يكتشف الوكلاء كل شيء تلقائياً عبر" },
  "set.mcpNoKeys": { en: "(OAuth 2.1, dynamic client registration, PKCE). No API keys needed.", ms: "(OAuth 2.1, pendaftaran klien dinamik, PKCE). Tanpa kunci API.", zh: "（OAuth 2.1、动态客户端注册、PKCE）。无需 API 密钥。", ta: "(OAuth 2.1, மாறும் க்ளையன்ட் பதிவு, PKCE). API விசைகள் தேவையில்லை.", ar: "(OAuth 2.1، تسجيل ديناميكي للعملاء، PKCE). لا حاجة لمفاتيح API." },
  "set.clientId": { en: "client id:", ms: "id klien:", zh: "客户端 ID：", ta: "க்ளையன்ட் ஐடி:", ar: "معرف العميل:" },
  "set.revoke": { en: "Revoke", ms: "Tarik balik", zh: "撤销", ta: "ரத்து", ar: "إلغاء" },
  "set.noAgents": { en: "No agents connected yet. Point any MCP client at the server URL — it registers itself.", ms: "Belum ada agent bersambung. Tunjuk mana-mana klien MCP ke URL pelayan — ia daftar sendiri.", zh: "尚无代理连接。将任何 MCP 客户端指向服务器 URL — 它会自行注册。", ta: "இன்னும் முகவர்கள் இணைக்கப்படவில்லை. எந்த MCP க்ளையன்டையும் சர்வர் URL-ஐ சுட்டிக்காட்டுங்கள் — அது தானே பதிவுசெய்யும்.", ar: "لا يوجد وكلاء متصلون بعد. وجّه أي عميل MCP إلى عنوان URL للخادم — سيسجل نفسه." },
  "set.socialTitle": { en: "Connected accounts (login)", ms: "Akaun bersambung (log masuk)", zh: "已连接的账户（登录）", ta: "இணைக்கப்பட்ட கணக்குகள் (உள்நுழைவு)", ar: "الحسابات المتصلة (تسجيل الدخول)" },
  "set.socialHelp": { en: "Link a Google account, then sign in with one click. More providers (Microsoft/Azure, GitHub) can be enabled later — same connector system.", ms: "Paut akaun Google, lepas tu log masuk satu klik. Pembekal lain (Microsoft/Azure, GitHub) boleh diaktifkan kemudian — sistem penyambung sama.", zh: "关联 Google 账户后一键登录。之后可启用更多提供商（Microsoft/Azure、GitHub）— 同一连接器系统。", ta: "Google கணக்கை இணைத்து, ஒரே கிளிக்கில் உள்நுழையவும். பிற வழங்குநர்கள் (Microsoft/Azure, GitHub) பின்னர் இயக்கக்கூடியவை — அதே இணைப்பான் அமைப்பு.", ar: "اربط حساب Google ثم سجّل الدخول بنقرة واحدة. يمكن تفعيل مزودين آخرين (Microsoft/Azure وGitHub) لاحقاً — بنفس نظام الربط." },
  "set.linked": { en: "linked", ms: "dipaut", zh: "已关联", ta: "இணைக்கப்பட்டது", ar: "مرتبط" },
  "set.unlink": { en: "Unlink", ms: "Nyahpaut", zh: "取消关联", ta: "இணைப்பை நீக்கு", ar: "إلغاء الربط" },
  "set.noLinked": { en: "No linked accounts yet.", ms: "Belum ada akaun dipaut.", zh: "尚未关联任何账户。", ta: "இன்னும் இணைக்கப்பட்ட கணக்குகள் இல்லை.", ar: "لا حسابات مرتبطة بعد." },
  "set.linkGoogle": { en: "Link Google account", ms: "Paut akaun Google", zh: "关联 Google 账户", ta: "Google கணக்கை இணைக்கவும்", ar: "ربط حساب Google" },
  "set.activeMode": { en: "ACTIVE · {mode}", ms: "AKTIF · {mode}", zh: "已启用 · {mode}", ta: "செயலில் · {mode}", ar: "نشط · {mode}" },
